### 3. internal/cli/daemon_role_constraints.go — RoleConfigFromEnv()

Add a function that reconstructs a partial RoleConfig from environment variables. This is the consumer-side counterpart to the env vars set in buildCommand:

```go
// RoleConfigFromEnv reconstructs a partial RoleConfig from LOOM_ROLE_* environment
// variables set by the daemon's buildCommand. Returns a RoleConfig with only the
// fields that were present in the environment. Returns a zero-value RoleConfig if
// no routing env vars are set.
func RoleConfigFromEnv() RoleConfig {
    var rc RoleConfig
    if v := os.Getenv("LOOM_ROLE_SKILLS"); v != "" {
        rc.Skills = strings.Split(v, ",")
    }
    if v := os.Getenv("LOOM_ROLE_PATH_PATTERNS"); v != "" {
        rc.PathPatterns = strings.Split(v, ",")
    }
    if v := os.Getenv("LOOM_ROLE_MAX_PRIORITY"); v != "" {
        if p, err := strconv.Atoi(v); err == nil {
            rc.MaxPriority = &p
        }
    }
    if v := os.Getenv("LOOM_ROLE_TASK_FILTER"); v != "" {
        rc.TaskFilter = v
    }
    return rc
}

// AgentEntryFromEnv reconstructs a partial AgentEntry from LOOM_AGENT_* environment
// variables set by the daemon's buildCommand.
func AgentEntryFromEnv() AgentEntry {
    var ae AgentEntry
    if v := os.Getenv("LOOM_AGENT_PATH_PATTERNS"); v != "" {
        ae.PathPatterns = strings.Split(v, ",")
    }
    if v := os.Getenv("BD_ACTOR"); v != "" {
        ae.Worktree = v
    }
    if v := os.Getenv("LOOM_ROLE"); v != "" {
        ae.Role = v
    }
    return ae
}
```

