func createPR(dir, headBranch, baseBranch, title, body string) (string, error) {
    args := []string{"pr", "create", "--base", baseBranch, "--head", headBranch, "--title", title, "--body", body}
    result := execCommand(dir, "gh", args...)
    if result.Err != nil {
